import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.x7b91k6X.js";const m=JSON.parse('{"title":"第 17 话 · 三盏绿灯，一次回滚：播放器的可观测与门禁","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.17-player-quality-metrics.md","filePath":"comics/EP.17-player-quality-metrics.md","lastUpdated":1793856207000}'),r={name:"comics/EP.17-player-quality-metrics.md"};function o(s,a,n,c,h,d){return l(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="第-17-话-·-三盏绿灯-一次回滚-播放器的可观测与门禁" tabindex="-1">第 17 话 · 三盏绿灯，一次回滚：播放器的可观测与门禁 <a class="header-anchor" href="#第-17-话-·-三盏绿灯-一次回滚-播放器的可观测与门禁" aria-label="Permalink to &quot;第 17 话 · 三盏绿灯，一次回滚：播放器的可观测与门禁&quot;">​</a></h1><blockquote><p>三盏绿灯照不到尾部的 5%，但用户就卡在那 5% 里。 本话漫画：<a href="./EP.17-player-quality-metrics.svg">EP.17-player-quality-metrics.svg</a></p></blockquote><h2 id="这一话的冲突" tabindex="-1">这一话的冲突 <a class="header-anchor" href="#这一话的冲突" aria-label="Permalink to &quot;这一话的冲突&quot;">​</a></h2><p>季度评审上，播放成功率 99.1%、崩溃率 0.05%、首帧均值 0.9s，三盏绿灯齐亮。 团队准备把新播放管道灰度放大到全量——直到客服月报里出现一条刺眼的数据： <strong>卡顿工单集中在中低端机型，而这一档设备恰好不在灰度样本里。</strong></p><p>Swifty 这才意识到：指标不是「算得对不对」的问题，而是「分母是谁」的问题。 这一话给出一套能挡住这次发布的口径与门禁。</p><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>Swifty</strong>：这次负责播放器指标看板，第一次尝到「被自己的数据骗」的滋味。</li><li><strong>Runtime 长老</strong>：只问三句话——分母是什么、样本从哪来、尾部在哪。</li><li><strong>产品同学</strong>：盯着采纳率与留存，希望「先上再说」。</li><li><strong>数据同学</strong>：把「均值」换成 P90 / P95 的人。</li></ul><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格-1-·-痛点现场-大盘全绿-用户卡顿" tabindex="-1">格 1 · 痛点现场：大盘全绿，用户卡顿 <a class="header-anchor" href="#格-1-·-痛点现场-大盘全绿-用户卡顿" aria-label="Permalink to &quot;格 1 · 痛点现场：大盘全绿，用户卡顿&quot;">​</a></h3><ul><li>大盘只报均值与成功率，P90 / P95 首帧从未埋点；</li><li>客服工单里「卡顿」集中在低端机，但看板没有机型维度；</li><li>结论：<strong>均值是平均值，不是体验值</strong>；尾部用户被统计口径抹掉了。</li></ul><h3 id="格-2-·-机制登场-口径对齐-三个数说清体验" tabindex="-1">格 2 · 机制登场：口径对齐，三个数说清体验 <a class="header-anchor" href="#格-2-·-机制登场-口径对齐-三个数说清体验" aria-label="Permalink to &quot;格 2 · 机制登场：口径对齐，三个数说清体验&quot;">​</a></h3><ul><li>卡顿工单一张就够：<code>session_id</code>、<code>stage=play</code>、<code>reason</code>、<code>stall_ms</code>、<code>buffer_ms</code>；</li><li>首帧 TTFF = 首帧上屏时间 − 开播指令时间，只减不猜；</li><li>卡顿率 = 卡顿会话数 / 播放会话数，分母必须与成功率同口径；</li><li>首帧同时看 P90 与 P95，红线：P90 ≥1.5s 或每会话卡顿 ≥1.2 次。</li></ul><h3 id="格-3-·-发布门禁-四枚红绿灯" tabindex="-1">格 3 · 发布门禁：四枚红绿灯 <a class="header-anchor" href="#格-3-·-发布门禁-四枚红绿灯" aria-label="Permalink to &quot;格 3 · 发布门禁：四枚红绿灯&quot;">​</a></h3><ul><li>① 崩溃率：阈值 ≤0.15%，实测 0.05% → 绿灯（n=1200 万会话）；</li><li>② 成功率：阈值 ≥97%，实测 99.1% → 绿灯（n=86 万会话）；</li><li>③ 卡顿 + 首帧：阈值 ≤1.2 次 / ≤1.5s，实测 0.73 次 / 1.2s → 绿灯（n=800 万会话）；</li><li>④ 灰度采纳率：阈值 ≥45%（目标 60%），实测 5% → 10% → <strong>红灯，回滚</strong>；</li><li>判定规则：四枚徽章取最差，任何一枚红灯即一票否决，保留回滚开关。</li></ul><h2 id="runtime-长老划重点" tabindex="-1">Runtime 长老划重点 <a class="header-anchor" href="#runtime-长老划重点" aria-label="Permalink to &quot;Runtime 长老划重点&quot;">​</a></h2><blockquote><p>三盏绿灯不代表安全：口径错配的样本，会把回滚推给下一批用户。</p></blockquote><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问：成功率 99.1% 已经很高，为什么还要看 P90 首帧和每会话卡顿次数？</strong></p><p>答：成功率只描述「有没有播出来」，不描述「播得好不好」。 首帧的 P90 描述开局等待，每会话卡顿次数描述过程中断； 三者合起来才能覆盖「能播、快播、不断」三段体验，缺一段就会漏掉尾部用户。</p><h2 id="去实验室" tabindex="-1">去实验室 <a class="header-anchor" href="#去实验室" aria-label="Permalink to &quot;去实验室&quot;">​</a></h2><ul><li>深读：<a href="./../17-player-quality-metrics">第 17 章 · 播放器与质量指标</a></li><li>动手：<code>examples/PlayerMetrics</code> —— 播放指标、门禁判定与 PSNR 的纯逻辑实现；</li><li>观察：把灰度样本改成「只含高端机」，看四枚徽章如何从全绿翻成红灯。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>漫画正篇到此告一段落。接下来把这一话的门禁表搬进真实看板， 再回到正文里补上端到端演练与复盘模板。</p><hr><p><sub>银翼工坊 Silverwing Workshop · EP.17 · 本话漫画 <a href="./EP.17-player-quality-metrics.svg">EP.17-player-quality-metrics.svg</a></sub></p>',25)])])}const p=e(r,[["render",o]]);export{m as __pageData,p as default};
